<script setup>
import {computed,ref} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import MovieGrid from '../components/MovieGrid.vue'
import StarRating from '../components/StarRating.vue'
import {findMovie,pick,movies,interstellar} from '../data/movies'
import {useMoviesStore} from '../stores/movies'
import '../assets/styles/views.css'
const route=useRoute(),router=useRouter(),store=useMoviesStore(),ratingPanel=ref(null),tag=ref(''),editing=ref(false),message=ref('')
const movie=computed(()=>findMovie(route.params.id)),info=computed(()=>movie.value?.id===1?interstellar:null)
const related=computed(()=>pick(7,2,4,12,15,16,5,6,10,3,11,8).filter(m=>m.id!==movie.value?.id).slice(0,6))
const byGenre=computed(()=>movies.filter(m=>m.id!==movie.value?.id&&m.genre===movie.value?.genre).slice(0,6))
function addTag(){store.addTag(movie.value.id,tag.value);tag.value='';editing.value=false}
function more(){router.push(`/app/movies/${movie.value.id}/recommendations`)}
</script>
<template><div v-if="movie" :key="movie.id" class="view"><button class="back" @click="router.push('/app/discover')">← Volver</button><section class="hero" style="min-height:400px"><h1>{{movie.title}}</h1><div class="actions"><span>{{movie.year}}</span><span v-if="info">{{info.duration}}</span></div><div class="chips"><span class="chip outline">{{movie.genre}}</span><template v-if="info"><span class="chip outline">Aventura</span><span class="chip outline">Drama</span></template></div><p><span class="rating-text">★ {{movie.rating}}</span> · Puntuación de ejemplo</p><div class="actions"><button class="btn-primary" @click="message='El tráiler estará disponible al conectar TMDB.'">Ver tráiler</button><button class="btn-secondary" @click="ratingPanel?.scrollIntoView({behavior:'smooth'})">Calificar</button><button class="btn-secondary" @click="store.toggleSave(movie)">{{store.savedIds.includes(movie.id)?'Quitar de mi lista':'Agregar a mi lista'}}</button></div><p v-if="message" role="status">{{message}}</p></section><section class="detail-info"><div class="section-stack"><h2>Sinopsis</h2><p class="muted">{{info?.synopsis||'Sinopsis disponible al conectar el catálogo real.'}}</p></div><div class="panel facts"><div><small>DIRECTOR</small>{{info?.director||'—'}}</div><div><small>GUION</small>{{info?.writer||'—'}}</div><div><small>DURACIÓN</small>{{info?.duration||'—'}}</div><div><small>GÉNEROS</small>{{movie.genre}}</div></div></section><section v-if="info"><h2>Reparto principal</h2><div class="cast"><div v-for="person in info.cast" :key="person[0]" class="cast-person"><div class="cast-avatar">{{person[0].split(' ').map(x=>x[0]).slice(0,2).join('')}}</div><strong>{{person[0]}}</strong><p class="muted">{{person[1]}}</p></div></div></section><section ref="ratingPanel" class="panel section-stack"><h3>Tu calificación</h3><StarRating :model-value="store.ratings[movie.id]||0" @update:model-value="store.rate(movie.id,$event)"/><p class="muted">Toca una estrella para calificar</p><h3>Tus tags personales</h3><div class="chips"><span v-for="t in store.tags[movie.id]||[]" :key="t" class="chip">{{t}}</span><button class="chip outline" @click="editing=!editing">+ Añadir tag</button></div><form v-if="editing" class="filter-row" @submit.prevent="addTag"><input v-model="tag" placeholder="Nuevo tag" required><button class="btn-primary">Añadir</button></form></section><section class="section-stack"><h2>Si te gustó esta película, también podrían interesarte…</h2><p class="muted">Basado en usuarios que calificaron alto {{movie.title}}. Recomendación de ejemplo.</p><MovieGrid :movies="related" size="S" :columns="6" :saved-ids="store.savedIds" @save="store.toggleSave"/><button class="btn-secondary center-button" @click="more">Ver más recomendaciones</button></section><MovieGrid title="Películas del mismo género" :movies="byGenre" size="S" :columns="6" show-more :saved-ids="store.savedIds" @save="store.toggleSave" @view-more="more"/></div><div v-else class="view"><h1>Película no encontrada</h1><RouterLink to="/app/discover">Volver al catálogo</RouterLink></div></template>
